"""Rules for mplot3d and generic member rules."""
from rules_base import cov, diff, na, miss, ALIAS

THREE_D_ARTIST = diff("Line2D / Collection / Patch / Text handles of an Axes3D", "a 2-D handle whose 3-D geometry the Axes3D keeps and projects before each draw")

RULES = [
    (r".*\.set", diff("update_props, typed setters", "conventions: `Artist.set(**kwargs)` becomes typed setters or update_props")),
    (r".*\.(draw|draw_pane|draw_grid|do_3d_projection)", na("drawing step: Figure::draw renders the whole tree")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.name", na("projection name constant; 3-D axes come from Figure::subplot_3d")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.convert_zunits", miss("unit conversion on 3-D axes (3-D plotting takes numbers)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_top_view", na("internal: resets the 2-D limits behind the 3-D view")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.get_z(gridlines|ticklines)", miss("gridline and tick-line artists of the z axis")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.apply_aspect", diff("Axes3D::set_aspect, Axes3D::set_box_aspect", "the 3-D layout applies the aspect")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.update_datalim", na("2-D data limits; 3-D axes autoscale over their own geometry")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(get|set)_autoscalez_on", cov("Axes3D::autoscale_on / Axes3D::set_axis_autoscale_on(Axis3::Z, ..)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(auto_scale_xyz|autoscale_view)", diff("Axes3D::autoscale, Axes3D::set_axis_autoscale_on", "autoscaling happens as data are added")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.get_w_lims", cov("Axes3D::limits")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(set|get)_[xyz]lim3d", ALIAS),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(twinx|twiny|secondary_xaxis|secondary_yaxis)", na("2-D axes methods inherited by 3-D axes, where they have no meaning")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(semilogx|semilogy|semilogz|loglog)", diff("Axes3D::set_xscale / set_yscale / set_zscale", "set a log scale on the axes")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.clabel", na("not implemented for 3-D axes in matplotlib either (returns None)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(can_zoom|can_pan)", diff("Axes3D::drag_zoom, Axes3D::pan_view, Axes3D::mouse_init", "3-D axes always pan and zoom")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.format_coord", diff("Axes3D::format_data", "the status bar readout of 3-D axes")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(get|set)_frame_on", diff("Axes3D::axis_on / set_axis_on / set_axis_off", "panes and axes are switched together")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(text3D|plot3D|contour3D|contourf3D|scatter3D|quiver3D|stem3D)", ALIAS),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(add_contour_set|add_contourf_set)", diff("Axes3D::contour / Axes3D::contourf", "contour sets are lifted when made")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.get_tightbbox", diff("Figure::tight_bbox", "tight boxes are computed for the whole figure")),
    (r"mpl_toolkits\.mplot3d\.art3d:(Collection3D|Line3D|Line3DCollection|Patch3D|Patch3DCollection|Path3DCollection|PathPatch3D|Poly3DCollection|Text3D)", THREE_D_ARTIST),
    (r"mpl_toolkits\.mplot3d\.art3d:(collection_2d_to_3d|patch_collection_2d_to_3d)", diff("Axes3D::add_collection3d", "the collection is lifted when added")),
    (r"mpl_toolkits\.mplot3d\.art3d:line_collection_2d_to_3d", diff("Axes3D::add_line_collection3d", "the collection is lifted when added")),
    (r"mpl_toolkits\.mplot3d\.art3d:poly_collection_2d_to_3d", diff("Axes3D::add_poly_collection3d", "the collection is lifted when added")),
    (r"mpl_toolkits\.mplot3d\.art3d:(patch_2d_to_3d|pathpatch_2d_to_3d)", diff("Axes3D::add_path_patch3d", "the patch is lifted when added")),
    (r"mpl_toolkits\.mplot3d\.art3d:text_2d_to_3d", diff("Axes3D::text, Axes3D::set_text_position", "3-D texts are made by the axes")),
    (r"mpl_toolkits\.mplot3d\.art3d:line_2d_to_3d", diff("Axes3D::plot_with", "3-D lines are made by the axes (zdir)")),
    (r"mpl_toolkits\.mplot3d\.art3d:Line3D\.(set_data_3d|get_data_3d|set_3d_properties)", miss("reading and replacing the 3-D points of a line (animations)")),
    (r"mpl_toolkits\.mplot3d\.art3d:.*\.set_sort_zpos", miss("the depth a collection sorts at")),
    (r"mpl_toolkits\.mplot3d\.art3d:Line3DCollection\.set_segments", miss("replacing the 3-D segments of a line collection")),
    (r"mpl_toolkits\.mplot3d\.art3d:(Patch3DCollection|Path3DCollection)\.set_depthshade", cov("Axes3D::set_depthshade")),
    (r"mpl_toolkits\.mplot3d\.art3d:(Patch3DCollection|Path3DCollection)\.get_depthshade", miss("reading the depth shading of a scatter")),
    (r"mpl_toolkits\.mplot3d\.art3d:(Patch3DCollection|Path3DCollection)\.set_3d_properties", miss("replacing the 3-D offsets of a scatter (animations)")),
    (r"mpl_toolkits\.mplot3d\.art3d:(Patch3D|PathPatch3D)\.set_3d_properties", diff("Axes3D::add_path_patch3d", "set when the patch is lifted")),
    (r"mpl_toolkits\.mplot3d\.art3d:Patch3D\.get_path", cov("Patch::shape (ProjectedOutline)")),
    (r"mpl_toolkits\.mplot3d\.art3d:Path3DCollection\.(set_sizes|set_linewidth)", cov("Collection::set_sizes / Collection::style on the returned handle")),
    (r"mpl_toolkits\.mplot3d\.art3d:.*\.(get_facecolor|get_edgecolor|set_facecolor|set_edgecolor|set_alpha)", cov("Collection::colors / Collection::set_facecolor / Collection::set_edgecolor, ArtistHandle::set_alpha")),
    (r"mpl_toolkits\.mplot3d\.art3d:Poly3DCollection\.set_zsort", diff("ZSort (Poly3DOptions)", "chosen when the polygons are added")),
    (r"mpl_toolkits\.mplot3d\.art3d:Poly3DCollection\.(set_verts|set_verts_and_codes|set_3d_properties)", miss("replacing the 3-D polygons of a collection")),
    (r"mpl_toolkits\.mplot3d\.art3d:Text3D\.(set_position_3d|set_z|set_3d_properties)", cov("Axes3D::set_text_position")),
    (r"mpl_toolkits\.mplot3d\.art3d:Text3D\.get_position_3d", miss("reading the 3-D anchor of a text")),
    (r"mpl_toolkits\.mplot3d\.art3d:Text3D\.get_tightbbox", diff("ArtistHandle::window_extent", "the projected text's extent")),
    (r"mpl_toolkits\.mplot3d\.axis3d:Axis\.get_minor_ticks", cov("Axis3D::ticks")),
    (r"mpl_toolkits\.mplot3d\.axis3d:Axis\.get_rotate_label", miss("reading whether a 3-D axis label rotates")),
    (r"mpl_toolkits\.mplot3d\.axis3d:Axis\.active_pane", na("drawing internals of the panes")),
    (r"mpl_toolkits\.mplot3d\.axis3d:Axis\.get_tightbbox", diff("Figure::tight_bbox", "tight boxes are computed for the whole figure")),
    (r"mpl_toolkits\.mplot3d\.axis3d:[XYZ]Axis\.axis_name", cov("Axis3D (Axis3)")),
    (r"mpl_toolkits\.mplot3d\.axis3d:[XYZ]Axis\.(get|set)_view_interval", cov("Axes3D::limits / Axes3D::set_limits")),
    (r"mpl_toolkits\.mplot3d\.axis3d:[XYZ]Axis\.(get|set)_data_interval", diff("Axes3D::autoscale", "data limits are kept by the axes for autoscaling")),
    (r"mpl_toolkits\.mplot3d\.proj3d:inv_transform", cov("Matrix4::inverse, Matrix4::project")),
]

KWARG_RULES = [
    (r"renderer", na("renderers are internal to drawing")),
    (r"emit", diff("shared axes", "shared axes always follow; limit callbacks are not available")),
    (r"auto", diff("Axes::set_axis_autoscale_on", "setting limits turns autoscaling off; turn it on again explicitly")),
    (r"(xmin|xmax|ymin|ymax|zmin|zmax)", ALIAS),
    (r"view_margin", miss("the extra 3-D view margin of set_xlim (`axes3d.automargin`)")),
    (r"axlim_clip", cov("option field axlim_clip / Axes3D::set_axlim_clip")),
    (r"minor", diff("Axis::set_minor_ticks / Axis::set_minor_ticklabels, Axis::ticklocs(minor)", "minor ticks have their own methods or a flag")),
    (r"which", diff("Axis::ticklabels(minor)", "major and minor ticks are asked separately")),
    (r"labelpad", cov("Axis::set_label_pad")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(set_[xyz]scale)\(value\)", cov("ScaleName argument")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(set_xlim|set_ylim|set_zlim)\(.*\)", cov("Axes3D::set_xlim / set_ylim / set_zlim")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_aspect\((anchor|share)\)", diff("Axes3D::set_anchor, Axes3D::share_view", "set separately")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(set_zmargin)\(m\)", cov("Axes3D::set_margin(Axis3::Z, m)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.margins\((x|y|z)\)", cov("Axes3D::set_margins / Axes3D::set_margin")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.autoscale\((enable|tight)\)", cov("Axes3D::autoscale, Axes3D::set_margins")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_[xyz]ticks\((ticks|labels)\)", cov("Axis3D::set_ticks / Axis3D::set_ticklabels")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_zticklabels\(labels\)", cov("Axis3D::set_ticklabels")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.zaxis_date\(tz\)", cov("Axis3D::axis_date")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.view_init\(vertical_axis\)", cov("Axes3D::set_vertical_axis")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.view_init\(share\)", cov("Axes3D::view_init_shared")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_proj_type\(focal_length\)", cov("ProjType (Persp with a focal length)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.mouse_init\((rotate_btn|pan_btn|zoom_btn)\)", cov("MouseButtons (rotate, pan, zoom)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(sharez|shareview)\(other\)", cov("Axes3D::share_z / Axes3D::share_view")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.format_zdata\(z\)", cov("Axes3D::format_data(Axis3::Z, z)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_zlabel\(zlabel\)", cov("Axes3D::set_zlabel(text)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_zinverted\(inverted\)", cov("Axes3D::set_inverted(Axis3::Z, ..)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.text\(s\)", cov("Axes3D::text(.., text, ..)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.text2D\((x|y|s)\)", cov("Axes3D::text2d(x, y, text)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.fill_between\((x1|y1|z1|x2|y2|z2)\)", cov("Axes3D::fill_between(first, second, ..)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(plot_surface|plot_trisurf)\((norm|vmin|vmax)\)", cov("colors (FaceColors with a colorizer)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.add_collection3d\(col\)", cov("Axes3D::add_collection3d(spec, ..)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.scatter\(c\)", cov("Scatter3DOptions::scatter (ScatterOptions::colors)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_title\(label\)", cov("Axes3D::set_title(text)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set_title\(loc\)", miss("left and right titles on 3-D axes")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.quiver\((X|Y|Z|U|V|W)\)", cov("Axes3D::quiver(positions, vectors, ..)")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.errorbar\(([xyz]err)\)", cov("Errorbar3DOptions::errors")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.errorbar\(([xyz](lo|up)lims)\)", cov("Errorbar3DOptions::lolims / uplims")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.stem\(label\)", diff("ArtistHandle::set_label on the returned stem parts", "set on the returned handle")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.set\(.*\)", diff("chained setters", "conventions: `ax.set(...)` becomes chained setters")),
    (r"mpl_toolkits\.mplot3d:Axes3D\.(get_zticks|get_zticklabels)\(.*\)", cov("Axis3D::ticklocs / Axis3D::ticklabels")),
]
